'ext.addUpResult': 'Result', 'ext.addUpDone': '{n} upstreams added', 'ext.addUpFailedN': '{n} failed', 'ext.toUpstreams': 'Go to upstreams →', 'ext.refreshed': 'Refreshed: {n} nodes, {out} included', 'ext.refreshedSame': 'Refreshed, content unchanged ({n} nodes, {out} included)',
